@@ -0,0 +1,93 @@
+import { CartService } from './cart.service';
+
+describe('CartService', () => {
+  it('legt bei leerem Warenkorb eine neue Position an', () => {
+    const service = new CartService();
+
+    service.addItem({
+      productId: 'P1',
+      productName: 'Ohrhörer Modell Compact',
+      supplierId: 'S1',
+      supplierName: 'Lieferant 1',
+      unitPrice: 27.5,
+      quantity: 2,
+    });
+
+    expect(service.items()).toEqual([
+      {
+        productId: 'P1',
+        productName: 'Ohrhörer Modell Compact',
+        supplierId: 'S1',
+        supplierName: 'Lieferant 1',
+        unitPrice: 27.5,
+        quantity: 2,
+      },
+    ]);
+  });
+
+  it('legt für dasselbe Produkt bei unterschiedlichen Lieferanten zwei getrennte Positionen an', () => {
+    const service = new CartService();
+
+    service.addItem({
+      productId: 'P1',
+      productName: 'Produkt 1',
+      supplierId: 'S1',
+      supplierName: 'Lieferant 1',
+      unitPrice: 27.5,
+      quantity: 1,
+    });
+    service.addItem({
+      productId: 'P1',
+      productName: 'Produkt 1',
+      supplierId: 'S2',
+      supplierName: 'Lieferant 2',
+      unitPrice: 29.9,
+      quantity: 1,
+    });
+
+    expect(service.items().length).toBe(2);
+    expect(service.items()[0].supplierId).toBe('S1');
+    expect(service.items()[1].supplierId).toBe('S2');
+  });
+
+  it('erhöht bei gleichem Produkt und gleichem Lieferant die Menge der bestehenden Position', () => {
+    const service = new CartService();
+
+    service.addItem({
+      productId: 'P1',
+      productName: 'Produkt 1',
+      supplierId: 'S1',
+      supplierName: 'Lieferant 1',
+      unitPrice: 27.5,
+      quantity: 2,
+    });
+    service.addItem({
+      productId: 'P1',
+      productName: 'Produkt 1',
+      supplierId: 'S1',
+      supplierName: 'Lieferant 1',
+      unitPrice: 27.5,
+      quantity: 3,
+    });
+
+    expect(service.items().length).toBe(1);
+    expect(service.items()[0].quantity).toBe(5);
+  });
+
+  it('gibt über items() den aktuellen Stand zurück, ohne dass eine neue Instanz nötig ist', () => {
+    const service = new CartService();
+
+    expect(service.items()).toEqual([]);
+
+    service.addItem({
+      productId: 'P1',
+      productName: 'Produkt 1',
+      supplierId: 'S1',
+      supplierName: 'Lieferant 1',
+      unitPrice: 27.5,
+      quantity: 1,
+    });
+
+    expect(service.items().length).toBe(1);
+  });
+});
diff --git a/seed-b-frontend/src/app/features/cart/cart.service.ts b/seed-b-frontend/src/app/features/cart/cart.service.ts
new file mode 100644
index 0000000..07a5a33
--- /dev/null
+++ b/seed-b-frontend/src/app/features/cart/cart.service.ts
@@ -0,0 +1,35 @@
+import { Injectable, signal } from '@angular/core';
+
+export interface CartItem {
+  productId: string;
+  productName: string;
+  supplierId: string;
+  supplierName: string;
+  unitPrice: number;
+  quantity: number;
+}
+
+@Injectable({ providedIn: 'root' })
+export class CartService {
+  private readonly _items = signal<CartItem[]>([]);
+  readonly items = this._items.asReadonly();
+
+  addItem(item: {
+    productId: string;
+    productName: string;
+    supplierId: string;
+    supplierName: string;
+    unitPrice: number;
+    quantity: number;
+  }): void {
+    this._items.update((items) => {
+      const index = items.findIndex((i) => i.productId === item.productId && i.supplierId === item.supplierId);
+      if (index === -1) {
+        return [...items, { ...item }];
+      }
+      const updated = [...items];
+      updated[index] = { ...updated[index], quantity: updated[index].quantity + item.quantity };
+      return updated;
+    });
+  }
+}
